  starterDiscardReload: ["Discard choices and reload", "선택을 버리고 다시 불러오기", "放弃选择并重新加载", "選択を破棄して再読み込み", "Descartar y recargar", "Abandonner les choix et recharger"],
  starterReferenceProducts: ["Reference products in {category}", "{category} 참고 상품", "{category} 中的参考商品", "{category} の参考商品", "Productos de referencia en {category}", "Produits de référence dans {category}"],
